type:
∀ {op : ℝ → ℝ → ℝ} {scale : ℝ} {scale_gt_one : 1 < scale} {nonneg : ∀ {x y : ℝ}, 0 ≤ x → 0 ≤ y → 0 ≤ op x y}
  {comm : ∀ (x y : ℝ), op x y = op y x} {zero_left : ∀ {x : ℝ}, 0 ≤ x → op 0 x = x}
  {diag : ∀ {x : ℝ}, 0 ≤ x → op x x = scale * x}
  {hom : ∀ {t x y : ℝ}, 0 ≤ t → 0 ≤ x → 0 ≤ y → op (t * x) (t * y) = t * op x y}
  {strict_left : ∀ {x x' y : ℝ}, 0 ≤ x → 0 ≤ y → x < x' → op x y < op x' y}
  {rearr :
    ∀ {a b c d : ℝ},
      0 ≤ a →
        a ≤ b →
          b ≤ c → c ≤ d → op (op a b) (op c d) ≤ op (op a c) (op b d) ∧ op (op a c) (op b d) ≤ op (op a d) (op b c)}
  {op_1 : ℝ → ℝ → ℝ} {scale_1 : ℝ} {scale_gt_one_1 : 1 < scale_1} {nonneg_1 : ∀ {x y : ℝ}, 0 ≤ x → 0 ≤ y → 0 ≤ op_1 x y}
  {comm_1 : ∀ (x y : ℝ), op_1 x y = op_1 y x} {zero_left_1 : ∀ {x : ℝ}, 0 ≤ x → op_1 0 x = x}
  {diag_1 : ∀ {x : ℝ}, 0 ≤ x → op_1 x x = scale_1 * x}
  {hom_1 : ∀ {t x y : ℝ}, 0 ≤ t → 0 ≤ x → 0 ≤ y → op_1 (t * x) (t * y) = t * op_1 x y}
  {strict_left_1 : ∀ {x x' y : ℝ}, 0 ≤ x → 0 ≤ y → x < x' → op_1 x y < op_1 x' y}
  {rearr_1 :
    ∀ {a b c d : ℝ},
      0 ≤ a →
        a ≤ b →
          b ≤ c →
            c ≤ d →
              op_1 (op_1 a b) (op_1 c d) ≤ op_1 (op_1 a c) (op_1 b d) ∧
                op_1 (op_1 a c) (op_1 b d) ≤ op_1 (op_1 a d) (op_1 b c)},
  { op := op, scale := scale, scale_gt_one := scale_gt_one, nonneg := nonneg, comm := comm, zero_left := zero_left,
        diag := diag, hom := hom, strict_left := strict_left, rearr := rearr } =
      { op := op_1, scale := scale_1, scale_gt_one := scale_gt_one_1, nonneg := nonneg_1, comm := comm_1,
        zero_left := zero_left_1, diag := diag_1, hom := hom_1, strict_left := strict_left_1, rearr := rearr_1 } →
    op = op_1 ∧ scale = scale_1
